// The Vite configuration of the NgDoc site "docs", generated by `ng add @ng-doc/add`
// from its build target. The vite-application and vite-dev-server targets run it. Edit it freely.

import path from "node:path";
import { fileURLToPath } from "node:url";

import { createNgDocAngularPlugins } from "@ng-doc/builder/generator/vite/angular/index.js";
import {
  createNgDocApplicationPlugin,
  createNgDocVitePlugin,
} from "@ng-doc/builder/generator/vite/index.js";

const workspaceRoot = fileURLToPath(new URL("../../", import.meta.url));
/** A workspace-relative path as an absolute one. */
const workspace = (file) => path.join(workspaceRoot, file);

/** The settings that differ between the build configurations, by Vite mode. */
const modes = { production: {}, development: { sourcemap: true } };
/** The settings of any other mode: the build target options without a configuration. */
const fallback = {};

export default ({ mode }) => {
  const settings = modes[mode] ?? fallback;
  return {
    base: mode === "production" ? "/docs/ngx-matx/" : "/",
    root: workspace("projects/docs/src"),
    resolve: {
      alias: {
        "@grumptech/ngx-matx/thin-scrollbars": workspace(
          "projects/ngx-matx/thin-scrollbars/_index.scss",
        ),
      },
    },
    server: { port: 4200 },
    publicDir: false,
    plugins: [
      createNgDocApplicationPlugin({
        workspaceRoot,
        sourceRoot: "projects/docs/src",
        browser: "projects/docs/src/main.ts",
        styles: [
          "node_modules/@ng-doc/app/styles/global.css",
          "node_modules/@ng-doc/app/styles/themes/dark.css",
          "projects/docs/src/styles.scss",
        ],
        assets: [
          {
            glob: "**/*",
            input: "node_modules/@ng-doc/app/assets",
            output: "assets/ng-doc/app",
          },
          {
            glob: "**/*",
            input: "node_modules/@ng-doc/ui-kit/assets",
            output: "assets/ng-doc/ui-kit",
          },
          "projects/docs/src/favicon.ico",
        ],
      }),
      createNgDocVitePlugin({
        analogLiveReload: true,
        angularPlugins: createNgDocAngularPlugins({
          tsconfig: workspace("projects/docs/tsconfig.app.json"),
          workspaceRoot,
          jit: false,
          disableTypeChecking: false,
          liveReload: true,
          inlineStylesExtension: "scss",
        }),
        angularComponentProbe: workspace("projects/docs/src/app/app.ts"),
        generator: {
          projectId: "docs",
          workspaceRoot,
          defaults: {
            docsRoot: workspace("projects/docs/src"),
            tsConfig: workspace("projects/docs/tsconfig.app.json"),
            outputRoot: workspace("ng-doc/docs"),
            cacheRoot: workspace(".cache/ng-doc/docs"),
          },
        },
      }),
    ],
    build: {
      outDir: workspace("dist/docs/browser"),
      emptyOutDir: true,
      sourcemap: settings.sourcemap,
    },
  };
};
